// The single catalogue of Phase 1 sounds: used by the audio engine, the sound test page (#/sons) and
// the licence check (assets/audio/LICENSES.md).
//
// Since Romain's recette 3 (2026-10-15, « Page d'essai à choix ») every sound is a list of versions,
// keyed « a » to « d ». Version « a » is the sound the game had before; the version the game plays is
// the one chosen (choices.ts: Romain's pick on this device, else DEFAULT_CHOICES). A version is
// generated by the code (a synthesis recipe of synth.ts with its round-robin takes), a recorded file
// (CC0 or public domain, with its own row in LICENSES.md, named by `licence`), or silence. Nothing
// else may enter the catalogue (CLAUDE.md « Sons »).

export type SoundId =
  | "sabot"
  | "hennissement-sortie"
  | "hennissement-ruade"
  | "hennissement-plainte"
  | "hennissement-joyeux"
  | "hennissement-fete"
  | "hennissement-surpris"
  | "carte-donne"
  | "carte-pose"
  | "carte-echange";

/** Mix bus a sound plays on (the master bus sits above it). */
export type SoundBus = "sfx";

/** Name of the synthesis recipe in synth.ts that renders a version. */
export type SynthRecipe =
  | "hoof"
  | "hoof-terre"
  | "hoof-paves"
  | "hoof-bois"
  | "neigh-sortie"
  | "neigh-ruade"
  | "neigh-plainte"
  | "neigh-joyeux"
  | "neigh-fete"
  | "neigh-surpris"
  | "card-donne"
  | "card-pose"
  | "card-echange";

/** The version keys, in the order the page shows them (« A » to « D »). */
export const VARIANT_KEYS = ["a", "b", "c", "d"] as const;
export type VariantKey = (typeof VARIANT_KEYS)[number];

export type VariantSource =
  /** Generated by the code: `takes` renders of the recipe, played round-robin. */
  | { kind: "synth"; recipe: SynthRecipe; takes: number }
  /** A recorded file (tried in order: .m4a, then .mp3); `licence` is its LICENSES.md row id. */
  | { kind: "file"; files: string[]; licence: string }
  /** Nothing plays. */
  | { kind: "silence" };

export type SoundVariant = { key: VariantKey; source: VariantSource };

export type SoundDef = {
  bus: SoundBus;
  /** The versions, « a » first; « a » is the sound the game had before the versions. */
  variants: SoundVariant[];
};

const synth = (key: VariantKey, recipe: SynthRecipe, takes = 1): SoundVariant => ({
  key,
  source: { kind: "synth", recipe, takes },
});

export const SOUNDS: Record<SoundId, SoundDef> = {
  sabot: {
    bus: "sfx",
    variants: [
      synth("a", "hoof", 3),
      // « Sur la terre »: a softer, lower, duller clop.
      synth("b", "hoof-terre", 3),
      // « Sur les pavés »: a bright, hard click with the ring of the iron shoe.
      synth("c", "hoof-paves", 3),
      // « Sur le bois »: a hollow knock, no thump.
      synth("d", "hoof-bois", 3),
    ],
  },
  "hennissement-sortie": { bus: "sfx", variants: [synth("a", "neigh-sortie")] },
  "hennissement-ruade": { bus: "sfx", variants: [synth("a", "neigh-ruade")] },
  "hennissement-plainte": { bus: "sfx", variants: [synth("a", "neigh-plainte")] },
  "hennissement-joyeux": { bus: "sfx", variants: [synth("a", "neigh-joyeux")] },
  "hennissement-fete": { bus: "sfx", variants: [synth("a", "neigh-fete")] },
  "hennissement-surpris": { bus: "sfx", variants: [synth("a", "neigh-surpris")] },
  "carte-donne": { bus: "sfx", variants: [synth("a", "card-donne")] },
  "carte-pose": { bus: "sfx", variants: [synth("a", "card-pose")] },
  "carte-echange": { bus: "sfx", variants: [synth("a", "card-echange")] },
};

export const SOUND_IDS = Object.keys(SOUNDS) as SoundId[];

/**
 * The sounds that are heard, in the game and on #/sons: the one switch of what plays. Romain, on
 * 2026-10-15: « laisse les sons de côté sauf les sabots des chevaux », then « Oui, que les sabots ».
 * So only the hooves sound for now: no neigh, no card sound. The other sounds keep their recipes,
 * their catalogue entries and their cue plan (game/cues.ts): adding an id back here brings that
 * sound back everywhere, with nothing else to change.
 */
export const ENABLED_SOUNDS: ReadonlySet<SoundId> = new Set<SoundId>(["sabot"]);

/** True when the sound is heard (ENABLED_SOUNDS). */
export function isSoundEnabled(id: SoundId): boolean {
  return ENABLED_SOUNDS.has(id);
}

/** One version of a sound, or undefined when that sound has no such version. */
export function variantOf(
  id: SoundId,
  key: VariantKey,
  catalogue: Record<SoundId, SoundDef> = SOUNDS,
): SoundVariant | undefined {
  return catalogue[id].variants.find((variant) => variant.key === key);
}
